// Same gap/staleness-detection shape as BNS's 'Check Buffer & Prepare Generator Input'.
const STALE_AFTER_DAYS = 14;
const MAX_ITEMS_PER_RUN = 20; // respects the monthly execution-cap warning in CLAUDE.md

const rows = $input.all().map(i => i.json);
const now = DateTime.now();

const withAge = rows.map(r => {
  const lu = r.last_updated ? DateTime.fromISO(String(r.last_updated)) : null;
  const ageDays = lu && lu.isValid ? now.diff(lu, 'days').days : Infinity; // blank/invalid = infinitely stale
  return { ...r, _ageDays: ageDays };
});

const stale = withAge
  .filter(r => r._ageDays >= STALE_AFTER_DAYS)
  .sort((a, b) => b._ageDays - a._ageDays)
  .slice(0, MAX_ITEMS_PER_RUN);

return stale.map(r => ({ json: { item: r.item, category: r.category, store: r.store, product_url: r.product_url || '' } }));

