// Validates the LLM's extraction against the required schema before it's trusted at all.
// Never a bare scrape-and-trust path, per CLAUDE.md.
const item = $('Loop Over Stale Items').first().json;
let parsed;
try {
  const raw = $input.first().json.content?.[0]?.text ?? '';
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { valid: false, item: item.item, store: item.store, reason: 'unparseable JSON from extraction' } }];
}

const priceOk = typeof parsed.price === 'number' && parsed.price > 0;
const storeOk = typeof parsed.store === 'string' && parsed.store.length > 0;
const itemOk = typeof parsed.item === 'string' && parsed.item.length > 0;

if (!priceOk || !storeOk || !itemOk) {
  return [{ json: { valid: false, item: item.item, store: item.store, reason: 'missing/invalid required field', raw: parsed } }];
}

return [{ json: { valid: true, ...parsed } }];

// 24-48h freshness gate (CLAUDE.md / architecture.md Section 5): a newly scraped price
// isn't trusted into Catalog until it's sat unchallenged for PROMOTE_AFTER_HOURS, and only
// if no newer scrape for the same item+store has landed since (which would supersede it).
const PROMOTE_AFTER_HOURS = 36; // middle of the 24-48h range CLAUDE.md specifies; adjust as needed

const rows = $input.all().map(i => i.json).filter(r => r.item && r.store);
const now = DateTime.now();

// Latest row per item+store
const latestByKey = new Map();
for (const r of rows) {
  const key = `${r.item}::${r.store}`;
  const scrapedAt = r.scraped_at ? DateTime.fromISO(String(r.scraped_at)) : null;
  const existing = latestByKey.get(key);
  if (!existing || (scrapedAt && scrapedAt > existing._scrapedAt)) {
    latestByKey.set(key, { ...r, _scrapedAt: scrapedAt });
  }
}

const ready = [];
for (const row of latestByKey.values()) {
  if (row.status !== 'pending') continue;
  if (!row._scrapedAt || !row._scrapedAt.isValid) continue;
  const ageHours = now.diff(row._scrapedAt, 'hours').hours;
  if (ageHours >= PROMOTE_AFTER_HOURS) {
    ready.push({ item: row.item, store: row.store, price: row.price, date: row.date });
  }
}

return ready.map(r => ({ json: r }));
